export function buildWhereClause<V extends Admit<T.WherePredicates>>(
	...value: [value?: V] & RefuseUndeclared<V>
): ReturnType<typeof _buildWhereClause>;
export function buildWhereClause<A extends NonEmptyArray<Admit<T.WherePredicate>>>(
	options: ListOptions<{ delimiter?: Delimiter.None | Delimiter.Trailing }>,
	...elements: A & RefuseUndeclared<A>
): ReturnType<typeof _buildWhereClause>;
export function buildWhereClause<A extends NonEmptyArray<Admit<T.WherePredicate>>>(
	...elements: A & RefuseUndeclared<A>
): ReturnType<typeof _buildWhereClause>;
export function buildWhereClause(...args: unknown[]) {
	if (args.length === 0 || (args.length === 1 && args[0] === undefined)) {
		return _buildWhereClause(args[0] as Parameters<typeof _buildWhereClause>[0]);
	}
	const prebuilt =
		args.length === 1 &&
		typeof args[0] === 'object' &&
		args[0] !== null &&
		(args[0] as { $type?: unknown }).$type === (TSKindId.WherePredicates as const);
	return prebuilt
		? _buildWhereClause(args[0] as Parameters<typeof _buildWhereClause>[0])
		: _buildWhereClause(
				(buildWherePredicates as (...a: unknown[]) => unknown)(...args) as Parameters<typeof _buildWhereClause>[0]
			);
}
function _buildWhereClause(value?: Admit<T.WherePredicates>): T.WhereClause.Bound {
	const _where_predicates = hydrateStored(value);
	const listView = ownerView(_where_predicates, '_item');
	if (listView.length === undefined) refuseReadStub('_where_predicates');
	const handle = currentHandle();
	if (handle !== undefined) admitChildren(handle, 'where_clause', { wherePredicates: _where_predicates });
	const node = {
		$type: TSKindId.WhereClause as const,
		$named: true as const,
		_where_predicates,
		$with: {
			wherePredicates: (...args: unknown[]) =>
				rebuilt(node, handle, () =>
					listSlotWith(
						args,
						{ kind: TSKindId.WherePredicates as const, optional: true, make: buildWherePredicates },
						(value?: Admit<T.WherePredicates>) => _buildWhereClause(value)
					)
				)
		},
		wherePredicates: () => hydrateStoredSlot(node, '_where_predicates'),
		length: listView.length,
		[LIST_ITEMS]: undefined,
		[LIST_READ]: () => listItems(ownerElements(node.wherePredicates(), 'items'), undefined),
		...LIST_METHODS,
		[Symbol.iterator]: listIterator,
		[Symbol.isConcatSpreadable]: true,
		[Symbol.unscopables]: Array.prototype[Symbol.unscopables],
		delimiter: listOption(listView.list, 'delimiter', undefined),
		$render: () => renderText(handle, node),
		toString: () => node.$render(),
		$trivia: {
			leading: (...items: unknown[]) => triviaSide(node, handle, 'leading', items),
			trailing: (...items: unknown[]) => triviaSide(node, handle, 'trailing', items)
		},
		$engine: handle && (() => handle.current)
	};
	defineListIndices(node, listView.length ?? 0);
	return stampBuilt(node) as unknown as T.WhereClause.Bound;
}

