export function buildTypeIdentifier<V extends Admit<T.Identifier>>(
	value: V & RefuseUndeclared<V>
): T.TypeIdentifier.Bound;
export function buildTypeIdentifier(value: Admit<T.Identifier>): T.TypeIdentifier.Bound {
	const _content = value;
	const handle = currentHandle();
	if (handle !== undefined) admitChildren(handle, 'type_identifier', { content: _content });
	const node = {
		$type: TSKindId.TypeIdentifier as const,
		$named: true as const,
		_content,
		$with: {
			content: (value: Admit<T.Identifier>) => rebuilt(node, handle, () => buildTypeIdentifier(value))
		},
		content: () => hydrateStoredSlot(node, '_content'),
		$render: () => renderText(handle, node),
		toString: () => node.$render(),
		$trivia: {
			leading: (...items: unknown[]) => triviaSide(node, handle, 'leading', items),
			trailing: (...items: unknown[]) => triviaSide(node, handle, 'trailing', items)
		},
		$engine: handle && (() => handle.current)
	};
	return stampBuilt(node) as unknown as T.TypeIdentifier.Bound;
}

